// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address[] memory tos, uint256[] memory vs) public {
        uint256 n = bound(tos.length, 1, 5);
        require(vs.length >= n);
        for (uint256 i = 0; i < n; i++) {
            vs[i] = bound(vs[i], 0, 1e30);
        }
        address[] memory t = new address[](n);
        uint256[] memory v = new uint256[](n);
        for (uint256 i = 0; i < n; i++) {
            t[i] = address(uint160(bound(uint256(uint160(tos[i])) + i, 1, type(uint160).max)));
            v[i] = vs[i];
        }
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        bool ok = c.transfer(t, v);
        assertTrue(ok, "successful transfer must return true");
    }
}
